#!/usr/bin/env bash
# AUTO-GENERATED by generate_configs.py — regenerate, don't hand-edit.
# Run mLSTM on MiniGrid-MemoryS13 for its seeds, ALL AT ONCE (parallel).
# Knobs (env vars):
#   PYTHON=.venv/bin/python   interpreter (default: repo .venv if present)
#   DEVICE=cuda               torch device (default cuda)
#   RUNS_DIR=runs/s13_baseline   output root
#   SEEDS="0 1 2"             seeds to run
#   PARALLEL=1                1 = seeds concurrently (default); 0 = sequential
#   EXTRA="--no-wandb"        extra train.py flags (e.g. --total-timesteps 8192)
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$HERE/../../.." && pwd)"
cd "$REPO_ROOT"

if [[ -z "${PYTHON:-}" ]]; then
  if [[ -x ".venv/bin/python" ]]; then PYTHON=".venv/bin/python"; else PYTHON="python"; fi
fi
DEVICE="${DEVICE:-cuda}"
RUNS_DIR="${RUNS_DIR:-runs/s13_baseline}"
SEEDS="${SEEDS:-0 1 2}"
PARALLEL="${PARALLEL:-1}"
EXTRA="${EXTRA:-}"
CFG="$HERE/../configs/s13_mLSTM_none_10M.yaml"
LOGDIR="$HERE/../_logs"; mkdir -p "$LOGDIR"

echo "[mLSTM] python=$PYTHON device=$DEVICE seeds=[$SEEDS] parallel=$PARALLEL"
pids=()
for s in $SEEDS; do
  if [[ "$PARALLEL" == "1" ]]; then
    "$PYTHON" -m train --config "$CFG" --seed "$s" \
        --runs-dir "$RUNS_DIR" --device "$DEVICE" $EXTRA \
        > "$LOGDIR/mLSTM_seed${s}.log" 2>&1 &
    pids+=("$!")
    echo "  launched mLSTM seed=$s (pid $!) → $LOGDIR/mLSTM_seed${s}.log"
  else
    echo "  mLSTM seed=$s (sequential)"
    "$PYTHON" -m train --config "$CFG" --seed "$s" \
        --runs-dir "$RUNS_DIR" --device "$DEVICE" $EXTRA
  fi
done
if [[ "$PARALLEL" == "1" ]]; then
  fail=0
  for p in "${pids[@]}"; do wait "$p" || fail=1; done
  [[ "$fail" == "0" ]] || { echo "[mLSTM] a seed FAILED — see $LOGDIR"; exit 1; }
fi
echo "[mLSTM] all seeds done."
